content:
Save the following as `index.html` and open it in a modern browser. It uses only the requested Three.js core ES module and includes custom orbit/zoom controls, animated traffic, tram priority, and a four-way pedestrian scramble.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Scramble Junction — Tram Priority</title>

  <style>
    :root {
      color-scheme: dark;
      --bg: #081019;
      --panel: rgba(12, 22, 33, 0.78);
      --line: rgba(151, 194, 218, 0.18);
      --text: #edf7ff;
      --muted: #8ca5b7;
      --cyan: #55e6ff;
      --green: #43f39a;
      --amber: #ffbd55;
      --red: #ff5268;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background: var(--bg);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
    }

    #app,
    #app canvas {
      position: fixed;
      inset: 0;
      width: 100%;
      height: 100%;
    }

    #app canvas {
      display: block;
      touch-action: none;
      cursor: grab;
    }

    #app canvas:active {
      cursor: grabbing;
    }

    .vignette {
      position: fixed;
      inset: 0;
      pointer-events: none;
      background:
        radial-gradient(circle at 50% 45%, transparent 42%, rgba(2, 7, 12, 0.34) 100%),
        linear-gradient(180deg, rgba(4, 10, 16, 0.2), transparent 24%);
    }

    .panel {
      position: fixed;
      z-index: 10;
      border: 1px solid var(--line);
      background: var(--panel);
      box-shadow: 0 18px 50px rgba(0, 0, 0, 0.26);
      backdrop-filter: blur(16px) saturate(125%);
      -webkit-backdrop-filter: blur(16px) saturate(125%);
    }

    .header {
      top: 24px;
      left: 24px;
      min-width: 285px;
      padding: 18px 20px;
      border-radius: 16px;
    }

    .eyebrow {
      display: flex;
      align-items: center;
      gap: 9px;
      color: var(--cyan);
      font-size: 10px;
      font-weight: 800;
      letter-spacing: 0.2em;
      text-transform: uppercase;
    }

    .live-dot {
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: var(--green);
      box-shadow: 0 0 12px var(--green);
      animation: pulse 1.8s ease-in-out infinite;
    }

    @keyframes pulse {
      50% {
        opacity: 0.45;
        transform: scale(0.8);
      }
    }

    h1 {
      margin: 9px 0 4px;
      font-size: 23px;
      line-height: 1;
      letter-spacing: -0.035em;
    }

    .subtitle {
      margin: 0;
      color: var(--muted);
      font-size: 12px;
    }

    .status {
      left: 24px;
      bottom: 24px;
      width: min(370px, calc(100vw - 48px));
      padding: 17px 18px 15px;
      border-radius: 16px;
    }

    .status-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      margin-bottom: 10px;
    }

    .phase-key {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      color: var(--amber);
      font-size: 10px;
      font-weight: 800;
      letter-spacing: 0.14em;
      transition: color 0.2s ease;
    }

    .phase-key::before {
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: currentColor;
      box-shadow: 0 0 10px currentColor;
      content: "";
    }

    .phase-time {
      color: var(--muted);
      font-size: 10px;
      font-variant-numeric: tabular-nums;
    }

    .status h2 {
      margin: 0;
      font-size: 20px;
      letter-spacing: -0.025em;
    }

    .status p {
      margin: 8px 0 14px;
      color: var(--muted);
      font-size: 12px;
      line-height: 1.5;
    }

    .readouts {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 7px;
      padding-bottom: 12px;
      border-bottom: 1px solid var(--line);
    }

    .readout {
      padding: 8px 9px;
      border: 1px solid rgba(255, 255, 255, 0.07);
      border-radius: 9px;
      background: rgba(255, 255, 255, 0.025);
    }

    .readout span {
      display: block;
      margin-bottom: 4px;
      color: var(--muted);
      font-size: 8px;
      font-weight: 800;
      letter-spacing: 0.13em;
    }

    .readout strong {
      font-size: 10px;
      font-weight: 750;
    }

    .progress {
      height: 3px;
      margin-top: 13px;
      overflow: hidden;
      border-radius: 4px;
      background: rgba(255, 255, 255, 0.08);
    }

    .progress i {
      display: block;
      width: 0;
      height: 100%;
      border-radius: inherit;
      background: linear-gradient(90deg, var(--cyan), var(--green));
    }

    .controls {
      top: 24px;
      right: 24px;
      display: grid;
      gap: 7px;
      padding: 8px;
      border-radius: 14px;
    }

    .control-label {
      padding: 4px 6px 6px;
      color: var(--muted);
      font-size: 9px;
      font-weight: 800;
      letter-spacing: 0.16em;
      text-transform: uppercase;
    }

    .button-row {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 6px;
    }

    button {
      min-height: 34px;
      padding: 8px 9px;
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: 8px;
      background: rgba(255, 255, 255, 0.045);
      color: var(--text);
      font: inherit;
      font-size: 10px;
      font-weight: 700;
      cursor: pointer;
      transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease;
    }

    button:hover {
      border-color: rgba(85, 230, 255, 0.45);
      background: rgba(85, 230, 255, 0.1);
    }

    button:active {
      transform: translateY(1px);
    }

    button.active {
      border-color: rgba(85, 230, 255, 0.55);
      color: var(--cyan);
    }

    .hint {
      position: fixed;
      right: 24px;
      bottom: 24px;
      z-index: 9;
      color: rgba(207, 226, 239, 0.58);
      font-size: 9px;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      pointer-events: none;
    }

    .legend {
      position: fixed;
      z-index: 9;
      top: 104px;
      right: 24px;
      display: flex;
      gap: 14px;
      color: rgba(207, 226, 239, 0.62);
      font-size: 9px;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      pointer-events: none;
    }

    .legend span {
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .legend i {
      width: 7px;
      height: 7px;
      border-radius: 50%;
    }

    #loading {
      position: fixed;
      inset: 0;
      z-index: 100;
      display: grid;
      place-items: center;
      background: #081019;
      transition: opacity 0.5s ease, visibility 0.5s ease;
    }

    #loading.hide {
      visibility: hidden;
      opacity: 0;
    }

    .loader {
      text-align: center;
    }

    .loader-ring {
      width: 42px;
      height: 42px;
      margin: 0 auto 16px;
      border: 2px solid rgba(85, 230, 255, 0.18);
      border-top-color: var(--cyan);
      border-radius: 50%;
      animation: spin 0.8s linear infinite;
    }

    @keyframes spin {
      to {
        transform: rotate(360deg);
      }
    }

    .loader strong {
      display: block;
      font-size: 11px;
      letter-spacing: 0.18em;
    }

    .loader small {
      display: block;
      margin-top: 7px;
      color: var(--muted);
    }

    @media (max-width: 700px) {
      .header {
        top: 12px;
        left: 12px;
        min-width: 0;
        padding: 13px 15px;
      }

      h1 {
        font-size: 18px;
      }

      .subtitle {
        display: none;
      }

      .legend {
        display: none;
      }

      .status {
        left: 12px;
        bottom: 12px;
        width: calc(100vw - 24px);
      }

      .controls {
        top: auto;
        right: 12px;
        bottom: 156px;
      }

      .hint {
        display: none;
      }
    }
  </style>
</head>

<body>
  <div id="app"></div>
  <div class="vignette"></div>

  <header class="panel header">
    <div class="eyebrow">
      <span class="live-dot"></span>
      Live intersection simulation
    </div>
    <h1>Scramble Junction</h1>
    <p class="subtitle">Pedestrian scramble · tram priority</p>
  </header>

  <div class="legend">
    <span><i style="background:#ffbd55"></i> Tram</span>
    <span><i style="background:#55e6ff"></i> Traffic</span>
    <span><i style="background:#43f39a"></i> Pedestrians</span>
  </div>

  <section class="panel status" aria-live="polite">
    <div class="status-head">
      <span id="phaseKey" class="phase-key">TRAM</span>
      <span id="phaseTime">0% complete</span>
    </div>
    <h2 id="phaseName">TRAM PRIORITY</h2>
    <p id="phaseDescription">
      The approaching tram has right of way. All vehicles and pedestrians remain stopped.
    </p>

    <div class="readouts">
      <div class="readout">
        <span>TRAM</span>
        <strong id="tramReadout">APPROACHING</strong>
      </div>
      <div class="readout">
        <span>CARS</span>
        <strong id="carReadout">STOPPED</strong>
      </div>
      <div class="readout">
        <span>WALK</span>
        <strong id="walkReadout">WAITING</strong>
      </div>
    </div>

    <div class="progress"><i id="progress"></i></div>
  </section>

  <nav class="panel controls" aria-label="Simulation controls">
    <div class="control-label">Camera views</div>
    <div class="button-row">
      <button class="active" data-view="overview">Overview</button>
      <button data-view="street">Street</button>
      <button data-view="tram">Tram</button>
      <button data-view="top">Top</button>
    </div>
    <div class="button-row">
      <button id="pauseButton">Pause</button>
      <button id="restartButton">Restart</button>
    </div>
  </nav>

  <div class="hint">Drag to orbit · Scroll to zoom · Double-click to reset</div>

  <div id="loading">
    <div class="loader">
      <div class="loader-ring"></div>
      <strong>BUILDING JUNCTION</strong>
      <small>Initializing traffic and pedestrian signals</small>
    </div>
  </div>

  <script type="module">
    import * as THREE from "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    const app = document.getElementById("app");
    const loading = document.getElementById("loading");

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.12;
    renderer.domElement.setAttribute("aria-label", "Animated 3D pedestrian scramble junction");
    app.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x081019);
    scene.fog = new THREE.Fog(0x081019, 58, 155);

    const camera = new THREE.PerspectiveCamera(
      43,
      window.innerWidth / window.innerHeight,
      0.1,
      260
    );

    const clock = new THREE.Clock();
    const clamp = THREE.MathUtils.clamp;
    const lerp = THREE.MathUtils.lerp;

    const M = {
      ground: new THREE.MeshStandardMaterial({
        color: 0x0b121a,
        roughness: 0.95
      }),
      asphalt: new THREE.MeshStandardMaterial({
        color: 0x111923,
        roughness: 0.93
      }),
      sidewalk: new THREE.MeshStandardMaterial({
        color: 0x34414d,
        roughness: 0.88
      }),
      curb: new THREE.MeshStandardMaterial({
        color: 0x66727c,
        roughness: 0.8
      }),
      concrete: new THREE.MeshStandardMaterial({
        color: 0x6c777d,
        roughness: 0.87
      }),
      white: new THREE.MeshStandardMaterial({
        color: 0xd9e4e8,
        roughness: 0.7
      }),
      yellow: new THREE.MeshStandardMaterial({
        color: 0xf4b83d,
        roughness: 0.62
      }),
      rail: new THREE.MeshStandardMaterial({
        color: 0x87929a,
        metalness: 0.88,
        roughness: 0.26
      }),
      sleeper: new THREE.MeshStandardMaterial({
        color: 0x252d34,
        roughness: 0.9
      }),
      trackBed: new THREE.MeshStandardMaterial({
        color: 0x171e25,
        roughness: 0.96
      }),
      glass: new THREE.MeshStandardMaterial({
        color: 0x173344,
        metalness: 0.42,
        roughness: 0.18
      }),
      black: new THREE.MeshStandardMaterial({
        color: 0x10171d,
        roughness: 0.55
      }),
      tramBody: new THREE.MeshStandardMaterial({
        color: 0xe6edf0,
        metalness: 0.3,
        roughness: 0.32
      }),
      tramRoof: new THREE.MeshStandardMaterial({
        color: 0x26323b,
        metalness: 0.55,
        roughness: 0.36
      }),
      trunk: new THREE.MeshStandardMaterial({
        color: 0x5c4635,
        roughness: 1
      }),
      foliage: new THREE.MeshStandardMaterial({
        color: 0x284d43,
        roughness: 0.95
      }),
      planter: new THREE.MeshStandardMaterial({
        color: 0x354b49,
        roughness: 0.9
      }),
      lamp: new THREE.MeshStandardMaterial({
        color: 0xffe6b2,
        emissive: 0xffbd67,
        emissiveIntensity: 1.5
      })
    };

    M.window = new THREE.MeshStandardMaterial({
      color: 0x83b9d0,
      emissive: 0x236a83,
      emissiveIntensity: 0.72,
      metalness: 0.25,
      roughness: 0.35
    });

    function box(w, h, d, material, x = 0, y = 0, z = 0, parent = scene) {
      const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
      mesh.position.set(x, y, z);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function cylinder(
      radiusTop,
      radiusBottom,
      height,
      material,
      x = 0,
      y = 0,
      z = 0,
      segments = 16,
      parent = scene
    ) {
      const mesh = new THREE.Mesh(
        new THREE.CylinderGeometry(radiusTop, radiusBottom, height, segments),
        material
      );
      mesh.position.set(x, y, z);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function beam(a, b, radius, material, parent = scene) {
      const start = new THREE.Vector3(...a);
      const end = new THREE.Vector3(...b);
      const direction = end.clone().sub(start);
      const length = direction.length();

      const mesh = new THREE.Mesh(
        new THREE.CylinderGeometry(radius, radius, length, 7),
        material
      );

      mesh.position.copy(start).add(end).multiplyScalar(0.5);
      mesh.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction.normalize()
      );
      mesh.castShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function makeTexture(width, height, draw) {
      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;

      const context = canvas.getContext("2d");
      draw(context, width, height);

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
      return texture;
    }

    function makeSignTexture(title, subtitle, accent = "#55e6ff") {
      return makeTexture(1024, 256, (ctx, w, h) => {
        ctx.fillStyle = "#0b151f";
        ctx.fillRect(0, 0, w, h);
        ctx.fillStyle = accent;
        ctx.fillRect(0, 0, 18, h);
        ctx.strokeStyle = "rgba(150,195,220,.25)";
        ctx.lineWidth = 5;
        ctx.strokeRect(2, 2, w - 4, h - 4);
        ctx.fillStyle = "#f1f8ff";
        ctx.font = "800 76px system-ui, sans-serif";
        ctx.fillText(title, 54, 112);
        ctx.fillStyle = accent;
        ctx.font = "700 28px system-ui, sans-serif";
        ctx.fillText(subtitle, 56, 170);
      });
    }

    const walkingTexture = makeTexture(128, 128, (ctx, w, h) => {
      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = "#43f39a";
      ctx.beginPath();
      ctx.moveTo(64, 25);
      ctx.lineTo(37, 92);
      ctx.lineTo(27, 92);
      ctx.lineTo(43, 48);
      ctx.lineTo(51, 48);
      ctx.lineTo(64, 76);
      ctx.lineTo(77, 48);
      ctx.lineTo(85, 48);
      ctx.lineTo(101, 92);
      ctx.lineTo(91, 92);
      ctx.lineTo(75, 48);
      ctx.closePath();
      ctx.fill();
    });

    const handTexture = makeTexture(128, 128, (ctx, w, h) => {
      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = "#ff5268";
      ctx.beginPath();
      ctx.moveTo(64, 25);
      ctx.lineTo(92, 78);
      ctx.lineTo(72, 78);
      ctx.lineTo(80, 108);
      ctx.lineTo(52, 108);
      ctx.lineTo(60, 78);
      ctx.lineTo(40, 78);
      ctx.closePath();
      ctx.fill();
    });

    // Lighting
    scene.add(new THREE.HemisphereLight(0x9bc8ef, 0x17202b, 1.65));

    const sun = new THREE.DirectionalLight(0xffe0b2, 3.1);
    sun.position.set(24, 38, 22);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    sun.shadow.camera.left = -55;
    sun.shadow.camera.right = 55;
    sun.shadow.camera.top = 55;
    sun.shadow.camera.bottom = -55;
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 110;
    sun.shadow.bias = -0.0003;
    scene.add(sun);

    const rim = new THREE.DirectionalLight(0x4ea8ff, 1.2);
    rim.position.set(-30, 18, -28);
    scene.add(rim);

    // Ground and road
    box(120, 0.4, 120, M.ground, 0, -0.35, 0);
    box(64, 0.12, 64, M.asphalt, 0, 0.01, 0);

    // Sidewalks around the four approaches
    box(64, 0.35, 10, M.sidewalk, 0, 0.18, -12);
    box(64, 0.35, 10, M.sidewalk, 0, 0.18, 12);
    box(10, 0.35, 64, M.sidewalk, -12, 0.18, 0);
    box(10, 0.35, 64, M.sidewalk, 12, 0.18, 0);

    box(64, 0.2, 0.28, M.curb, 0, 0.3, -7);
    box(64, 0.2, 0.28, M.curb, 0, 0.3, 7);
    box(0.28, 0.2, 64, M.curb, -7, 0.3, 0);
    box(0.28, 0.2, 64, M.curb, 7, 0.3, 0);

    // Central scramble island
    const island = cylinder(
      8.25,
      8.25,
      0.4,
      M.concrete,
      0,
      0.28,
      0,
      64
    );
    island.receiveShadow = true;

    const islandCurb = new THREE.Mesh(
      new THREE.TorusGeometry(8.35, 0.18, 10, 64),
      M.curb
    );
    islandCurb.rotation.x = Math.PI / 2;
    islandCurb.position.y = 0.46;
    islandCurb.castShadow = true;
    scene.add(islandCurb);

    // Road lane markings
    for (let x = -30; x <= 30; x += 8) {
      box(3.2, 0.025, 0.12, M.white, x, 0.09, -4.6);
      box(3.2, 0.025, 0.12, M.white, x, 0.09, 4.6);
    }

    for (let z = -30; z <= 30; z += 8) {
      box(0.12, 0.025, 3.2, M.white, -4.6, 0.09, z);
      box(0.12, 0.025, 3.2, M.white, 4.6, 0.09, z);
    }

    // Zebra crossings
    function createZebra(axis, fixed, start, end) {
      for (let i = 0; i < 10; i++) {
        const position = start + (i / 9) * (end - start);
        if (axis === "x") {
          box(9.4, 0.035, 1.15, M.white, position, 0.125, fixed);
        } else {
          box(1.15, 0.035, 9.4, M.white, fixed, 0.125, position);
        }
      }
    }

    createZebra("x", -10.5, -4.5, 4.5);
    createZebra("x", 10.5, -4.5, 4.5);
    createZebra("z", -10.5, -4.5, 4.5);
    createZebra("z", 10.5, -4.5, 4.5);

    // Stop lines
    box(0.35, 0.035, 9.5, M.white, -14, 0.12, 0);
    box(0.35, 0.035, 9.5, M.white, 14, 0.12, 0);
    box(9.5, 0.035, 0.35, M.white, 0, 0.12, -14);
    box(9.5, 0.035, 0.35, M.white, 0, 0.12, 14);

    // Tram tracks
    function createTrack(axis) {
      box(100, 0.07, 4.2, M.trackBed, 0, 0.08, 0);

      if (axis === "x") {
        box(100, 0.13, 0.12, M.rail, 0, 0.19, -1.35);
        box(100, 0.13, 0.12, M.rail, 0, 0.19, 1.35);

        for (let x = -48; x <= 48; x += 2.2) {
          box(0.24, 0.12, 3.2, M.sleeper, x, 0.11, 0);
        }

        box(100, 0.03, 0.12, M.yellow, 0, 0.14, -1.78);
        box(100, 0.03, 0.12, M.yellow, 0, 0.14, 1.78);
      } else {
        box(4.2, 0.07, 100, M.trackBed, 0, 0.08, 0);

        box(0.12, 0.13, 100, M.rail, -1.35, 0.19, 0);
        box(0.12, 0.13, 100, M.rail, 1.35, 0.19, 0);

        for (let z = -48; z <= 48; z += 2.2) {
          box(3.2, 0.12, 0.24, M.sleeper, 0, 0.11, z);
        }

        box(0.12, 0.03, 100, M.yellow, -1.78, 0.14, 0);
        box(0.12, 0.03, 100, M.yellow, 1.78, 0.14, 0);
      }
    }

    createTrack("x");
    createTrack("z");

    // Signal materials
    const vehicleLensMaterials = [];
    const pedestrianPanelMaterials = [];

    function createVehicleSignal(position, rotation) {
      const group = new THREE.Group();
      group.position.copy(position);
      group.rotation.y = rotation;
